const max = (n1: number, n2: number): number =>
    (n1 > n2) ? n1 : n2;

// Compute the height of an E-AST
const Eheight = (e: E): number =>
    isNumExp(e) ? 0 :
    isAddExp(e) ? max(Eheight(e.left), Eheight(e.right)) + 1 :
    isMulExp(e) ? max(Eheight(e.left), Eheight(e.right)) + 1 :
    0;
